insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p158', 'allemand', '3AS', 17, 158, 'L8 3AS p158 — Steffi-Text Übungen : R/F + Ergänzen (Bewerbung/Rundgang/…) + 6 Antworten', E'1. Stimmt das ? Stimmt das nicht ? Kreuzen Sie an. (R/F)\n- Steffi ist arbeitslos.\n- Sie hilft den Jugendlichen, die Probleme haben.\n- Sie arbeitet nur im Büro.\n- Steffi diskutiert viel mit diesen Jugendlichen.\n- Die Jugendlichen waren für die Vorbereitung des Straßenfestes sehr motiviert.\n2. Ergänzen Sie. (verteilen auf · Bewerbung · aufnehmen · Abschluss · Rundgang · erwähnen)\n- Dieser Kandidat hat seine ……… nicht unterschrieben.\n- Sie versucht, Kontakt mit den Jugendlichen ……… zu ………\n- Der Schulleiter macht morgens einen ……… durch die Schule.\n- Der Chef hat viele Arbeitsprobleme ………\n- Er ……… die Forschungsarbeit ……… drei Leute.\n- Dieser Jugendliche bekommt keinen Arbeitsplatz, denn sein ……… ist schlecht.\n3. Antworten Sie.\n1. Welche Arbeit hat Steffi ?\n2. In welcher Stadt arbeitet sie ?\n3. Um wen kümmert sie sich ?\n4. Was für Probleme haben die Jugendlichen ?\n5. Warum geht Steffi auf offenen Rundgang ?\n6. Weshalb bezeichnet sie das Strassenfest als ein Erfolgserlebnis ?\nFoto : Radarbildschirm · Mann am Kontrollpult.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p159', 'allemand', '3AS', 17, 159, 'L8 3AS p159 — Steffi ist hilfsbereiter als… (Komparativ/Superlativ : älter/der Älteste/besser/am besten)', E'Steffi ist hilfsbereiter als…\n1. Üben Sie zu zweit wie im Beispiel.\n- Wie alt ist Peter ? — Siebzehn.\n- Und Monika ? — Monika ist achtzehn.\n- Sie ist älter als Peter. Und wie alt ist Robert ?\n- Er ist der Älteste, er ist zwanzig.\nTabelle : Peter alt/17 · groß/1,70 · schwer 60 Kg · schnell : 100 M Lauf 15 Sek · Monika alt/18 · groß/1,75 · leicht 50 Kg · 14,8 Sek · Robert alt/20 · groß/1,85 · schwer 75 Kg · 14,0 Sek\n2. Ergänzen Sie die Tabelle.\ngut · ……… · lieber als · ……… · viel · ……… · ……… · am schnellsten · groß · ……… · ……… · höher · nah · ………\n3. Üben Sie zu zweit wie im Beispiel.\n- Arbeitet Herr Weber so gut wie Herr Müller ?\n- Nein, er arbeitet besser als Herr Müller.\n- Und Frau Weber ?\n- Sie arbeitet am besten.\nTabelle : arbeiten/gut · übersetzen/viel · arbeiten/gern · hoch bezahlt werden · dem Chef nahe stehen', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p160', 'allemand', '3AS', 17, 160, 'L8 3AS p160 — Komparativ/Superlativ ergänzen + Endungen -heit/-keit/-schaft/-ung/-bar/-los', E'4. Ergänzen Sie den Komparativ oder den Superlativ.\nPeter ist fleißig · Thomas ist ……… er · Inge ist am ………sten\nRuth ist freundlich · Doris ist ………… · Hans ist …… ……………\nEr hat Inge gern · Er hat Lisa ………… · Er hat Lina …… ……………\nDas Haus ist nah · Die Schule ist ………… · Das Gymnasium ist … …\nMonika lernt gut · Lisa lernt ………… · Erich lernt …… ……………\nDas Heft ist teuer · Das Buch ist ……… · Das Handy ist ……………\nDu isst viel · Ich esse ………… · Ingrid isst …… ……………\n5. Ergänzen Sie.\n- Franz ist so alt …. Erich. Tobias ist älter ….. Peter. Karl ist der ……………\n- Inge schrieb eine gut… Arbeit. Doris schrieb eine besser….. Arbeit. Erika schrieb die ……… Arbeit.\n- Welcher Weg ist der kurz……… zur Schule ?\n- Ich habe viele Postkarten. Du hast …… Postkarten …… ich. Peter hat die ……… Postkarten.\n6. Ergänzen Sie. (heit / keit / schaft / ung / bar / los)\n- Während meiner Kind…… hatte ich keine Sorgen.\n- Diese Tätig…… gefällt unserem Sohn nicht.\n- Das ist eine grosse Verantwort…… für Sie.\n- Unsere Gesund…… ist unser Reichtum.\n- Er hat keine Kinder. Er ist kinder……\n- Als Lehrling musst du diese Gelegen…… nicht verpassen.\n- Die Jugendlichen dürfen nie die Hoffn…… aufgeben.\n- Der Arzt freut sich über die Heil…… des Kranken.\n- Unsere Mann…… hat den Wettkampf nicht gewinnen können.\n- Diese Arbeit erfordert große Gewissenhaftig……\n- Deine Schrift ist unles……', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p161', 'allemand', '3AS', 17, 161, 'L8 3AS p161 — Die Traumberufe : Mathias (Pilot) + Markus (Fußballprofi) + R/F', E'Die Traumberufe\nMathias : Ich würde gerne Pilot werden, weil man dann neue Länder besuchen kann, ohne etwas zu bezahlen. Es macht außerdem Spaß zu fliegen. Der Beruf ist nicht so anstrengend, außer dass man vielleicht nachts fliegen muss. Starten und landen muss der Pilot selbst machen. In der Luft übernimmt dann der Autopilot die Steuerung ; dabei kann der Pilot kurz etwas essen oder sich mit seinen Kollegen unterhalten. Die Menschen, die im Flugzeug sitzen, vertrauen den Piloten ihr Leben an. Aber es gibt einen Nachteil : man isst fast nie zu Hause, sondern immer unterwegs.\n1. Stimmt das ? Stimmt das nicht ? Kreuzen Sie an. (R/F)\n- Mathias will als Pilot arbeiten.\n- Die Arbeit des Piloten ist nicht schwer.\n- Als Pilot kann man immer zu Hause sein.\nMarkus : Mein Traumberuf ist Fußballprofi zu werden, weil ich mir diesen Beruf immer gewünscht habe. Im Moment bin ich in einem kleinen Verein : Er heißt SV Niederursel. Hier trainiere ich jeden Mittwoch und Freitag. Samstag und Sonntag haben wir Punktspiele. Aber leider darf ich im Moment nicht mitspielen, weil ich für zwei einhalb Monate gesperrt bin. Ich kann nichts dagegen machen, außer warten. Wenn ich es schaffe, würde ich gern in der 2. Liga oder in der 3. Liga spielen, um mich zu verbessern, und um mehr zu lernen. Wenn ich soweit wäre, würde ich gern in der 1. Liga spielen und mein Bestes geben.\n2. Stimmt das ? Stimmt das nicht ? Kreuzen Sie an. (R/F)\n- Markus will Fussballspieler werden.\n- Markus trainiert jeden Tag.\n- Markus möchte in der 2. Liga spielen.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p162', 'allemand', '3AS', 17, 162, 'L8 3AS p162 — Traumberufe : Anne (Ärztin) + Inge (Filmstar) + R/F', E'Mein Traumberuf : Ärztin\nAnne : Ich würde gerne Ärztin werden, weil es mir Spaß macht, Alten und Kranken zu helfen. In einer Praxis würde ich nicht gerne arbeiten, weil ich es langweilig finde. Im Krankenhaus ist es viel spannender ; da kommen Tag und Nacht kranke Leute und am liebsten würde ich in der Notaufnahme arbeiten.\n3. Stimmt das ? Stimmt das nicht ? Kreuzen Sie an. (R/F)\n- Als Ärztin wird Anne den Kranken helfen.\n- Sie wird besser in einer Praxis arbeiten.\n- Im Krankenhaus kommen immer viele Leute.\nInge : «Mein Traumberuf wäre, Filmstar zu werden. Als Filmstar ist man sehr bekannt. Um Filmstar zu werden, muss man lange hart arbeiten. Man muss jedes Mal eine neue Rolle spielen und das verlangt natürlich viel Zeit und Arbeit. Es ist auch spannend, Filme im Ausland zu drehen. Dafür muss man mehrere Sprachen lernen. Da sieht man andere Länder, andere Menschen und andere Kulturen. Als Filmstar ist man immer modern angezogen und toll geschminkt. Aktionsfilme für Kinos finde ich am interessantesten ; so kann man auch viel Geld verdienen !»\n4. Stimmt das ? Stimmt das nicht ? Kreuzen Sie an. (R/F)\n- Als Filmstar ist man nicht sehr bekannt.\n- Filmstar zu werden braucht viel Zeit und Arbeit.\n- Aktionsfilme findet Inge langweilig.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
